<template>
  <div class="raw-panel">
    <!-- 工具栏 -->
    <div class="raw-toolbar">
      <div class="toolbar-left">
        <Code2 :size="14" class="raw-icon" />
        <span class="raw-title">Raw 模式</span>
        <span
          class="status-dot"
          :class="{ dirty: isDirty, error: !!parseError }"
          :title="parseError ? `解析错误：${parseError}` : isDirty ? '有未应用的改动' : '已同步'"
        ></span>
      </div>
      <div class="toolbar-right">
        <button class="icon-btn" title="格式化 JSON" @click="onFormat" :disabled="!!parseError">
          <Wand2 :size="13" />
        </button>
        <button class="icon-btn" title="复制到剪贴板" @click="onCopy">
          <Copy :size="13" />
        </button>
        <button class="apply-btn" :disabled="!canApply" @click="onApply">
          <Check :size="12" />
          <span>应用</span>
        </button>
      </div>
    </div>

    <!-- 编辑器主体（行号 + JSON textarea） -->
    <div class="raw-editor">
      <div class="line-numbers me-mono">
        <div v-for="n in lineCount" :key="n">{{ n }}</div>
      </div>
      <textarea
        ref="textareaRef"
        class="raw-textarea me-mono"
        :class="{ 'has-error': !!parseError }"
        spellcheck="false"
        :value="draft"
        @input="onInput"
        @keydown.tab.prevent="onTab"
      ></textarea>
    </div>

    <!-- 错误提示条 -->
    <div v-if="parseError" class="raw-error">
      <AlertTriangle :size="13" />
      <span>JSON 解析错误：{{ parseError }}</span>
    </div>

    <!-- 底部状态栏 -->
    <div class="raw-statusbar">
      <span class="status-item">JSON</span>
      <span class="dot"></span>
      <span class="status-item">UTF-8</span>
      <span class="dot"></span>
      <span class="status-item">{{ lineCount }} 行</span>
      <span class="dot"></span>
      <span class="status-item">{{ draft.length }} 字符</span>
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref, computed, watch } from 'vue';
import { Code2, Wand2, Copy, Check, AlertTriangle } from 'lucide-vue-next';

const props = defineProps<{
  /** 上层传入的当前 meta 数据（reactive proxy 或普通对象皆可） */
  value: any;
}>();

const emit = defineEmits<{
  /** 用户点击"应用"按钮：抛出已成功解析的对象，由上层 setMeta 接收 */
  (e: 'apply', parsed: any): void;
}>();

/** 把任意对象格式化为 JSON 字符串（缩进 2） */
function format(obj: any): string {
  try {
    return JSON.stringify(obj, null, 2);
  } catch {
    return '';
  }
}

/**
 * 当前文本草稿。
 *
 * - 跟随 props.value 变化时刷新（用户在场景模式编辑后，切回 raw 应该看到最新 JSON）
 * - 用户在 raw 模式输入时，独立维护本地草稿，不立刻回写父级
 * - 点击"应用"按钮才校验并 emit('apply', parsed)
 */
const draft = ref<string>(format(props.value));

watch(
  () => props.value,
  (newVal) => {
    // 仅当外部数据真的变化（而非用户当前正在编辑的草稿）时同步
    const formatted = format(newVal);
    if (formatted !== draft.value) {
      // 注意：如果用户当前有未应用的脏改动，外部数据更新会覆盖它
      // demo 阶段简化处理；后续可加 dirty 守护询问"丢弃改动？"
      draft.value = formatted;
    }
  },
  { deep: true },
);

const onInput = (e: Event) => {
  draft.value = (e.target as HTMLTextAreaElement).value;
};

/** Tab 键插入两个空格（不离开 textarea） */
const textareaRef = ref<HTMLTextAreaElement | null>(null);
const onTab = () => {
  const ta = textareaRef.value;
  if (!ta) return;
  const start = ta.selectionStart;
  const end = ta.selectionEnd;
  draft.value = draft.value.slice(0, start) + '  ' + draft.value.slice(end);
  // 下一帧再设光标位置（textarea 重渲染后）
  requestAnimationFrame(() => {
    ta.selectionStart = ta.selectionEnd = start + 2;
  });
};

/** 解析当前草稿，返回 {ok, value/error} */
const parsed = computed<{ ok: true; value: any } | { ok: false; error: string }>(() => {
  try {
    const v = JSON.parse(draft.value);
    if (!v || typeof v !== 'object' || Array.isArray(v)) {
      return { ok: false, error: 'JSON 根必须是对象' };
    }
    return { ok: true, value: v };
  } catch (err) {
    return { ok: false, error: (err as Error).message };
  }
});

const parseError = computed(() => (parsed.value.ok ? '' : parsed.value.error));

/** 草稿与外部 value 的 JSON 表达不一致时为 dirty */
const isDirty = computed(() => draft.value !== format(props.value));

/** 仅当解析成功且数据变化时允许应用 */
const canApply = computed(() => parsed.value.ok && isDirty.value);

const lineCount = computed(() => Math.max(1, draft.value.split('\n').length));

const onApply = () => {
  if (!parsed.value.ok) return;
  if (!isDirty.value) return;
  emit('apply', parsed.value.value);
};

const onFormat = () => {
  if (!parsed.value.ok) return;
  draft.value = format(parsed.value.value);
};

const onCopy = async () => {
  try {
    await navigator.clipboard.writeText(draft.value);
    // eslint-disable-next-line no-console
    console.log('[RawMode] copied to clipboard');
  } catch (err) {
    // eslint-disable-next-line no-console
    console.warn('[RawMode] clipboard failed:', err);
  }
};
</script>

