<template>
  <Teleport to="body">
    <Transition name="me-modal">
      <div
        v-if="visible"
        class="me-modal-mask meta-editor-scope"
        @click="onMaskClick"
      >
        <div
          class="me-modal-card"
          role="dialog"
          aria-modal="true"
          @click.stop
        >
          <div class="me-modal-header">
            <Upload :size="18" class="me-modal-icon" />
            <div class="me-modal-title">导入项目</div>
          </div>
          <div class="me-modal-body">
            <div class="source-tabs">
              <button
                class="source-tab"
                :class="{ active: source === 'local' }"
                type="button"
                @click="source = 'local'"
              >
                <FileUp :size="14" />
                <span>本地文件</span>
              </button>
              <button
                class="source-tab"
                :class="{ active: source === 'remote' }"
                type="button"
                @click="source = 'remote'"
              >
                <Globe :size="14" />
                <span>远程 URL</span>
              </button>
            </div>

            <div v-if="source === 'local'" class="source-pane">
              <p class="source-desc">
                选择本地的 <code>.json</code> 配置或 <code>.zip</code> 项目包。
              </p>
              <p class="source-hint">
                <span>导入 <code>.json</code> 时</span>
                <span>编辑器会询问你授权一个目录，按相对路径加载素材到 FileBundle。</span>
              </p>
            </div>

            <div v-else class="source-pane">
              <label class="url-label">配置 URL（仅支持 .json）</label>
              <input
                ref="urlInputRef"
                v-model="urlInput"
                type="url"
                class="me-input url-input"
                placeholder="https://cdn.example.com/proj/splat.json"
                spellcheck="false"
                autocomplete="off"
                @keydown.enter="trySubmitRemote"
              />
              <p v-if="urlError" class="url-error">
                <AlertCircle :size="13" />
                {{ urlError }}
              </p>
              <p class="source-hint">
                <span>编辑器会先 <code>fetch</code> 该 URL 解析 JSON，</span>
                <span>再以它的所在目录为 baseURL 自动拉取相对路径素材。</span>
                <span class="cors-hint">⚠ 远程站点必须允许跨域 (CORS)，否则会被浏览器阻断。</span>
              </p>
            </div>
          </div>
          <div class="me-modal-actions">
            <button class="me-btn" type="button" @click="cancel">取消</button>
            <button
              class="me-btn me-btn-primary"
              type="button"
              :disabled="!canSubmit"
              @click="submit"
            >
              {{ source === 'local' ? '选择文件...' : '加载' }}
            </button>
          </div>
        </div>
      </div>
    </Transition>
  </Teleport>
</template>

<script lang="ts">
/**
 * 命令式"导入来源"对话框。
 *
 * 使用：
 * ```ts
 * const choice = await importSourceDialog();
 * // choice = 'local' | { url: string } | null（用户取消）
 * ```
 *
 * 必须在某处挂载一次 <ImportSourceDialog />（推荐 MetaEditor 根节点，与 ConfirmDialog 同位置）。
 */
import { ref } from 'vue';
import { Upload, FileUp, Globe, AlertCircle } from 'lucide-vue-next';

export type ImportChoice = 'local' | { url: string } | null;

interface PendingImport {
  resolve: (v: ImportChoice) => void;
}

const _queue = ref<PendingImport[]>([]);

/** 命令式调用：弹出对话框，返回 Promise<ImportChoice> */
export function importSourceDialog(): Promise<ImportChoice> {
  return new Promise<ImportChoice>((resolve) => {
    _queue.value.push({ resolve });
  });
}
</script>

<script setup lang="ts">
import { computed, nextTick, watch } from 'vue';

const visible = computed(() => _queue.value.length > 0);
const current = computed(() => _queue.value[0] ?? null);

const source = ref<'local' | 'remote'>('local');
const urlInput = ref('');
const urlError = ref('');
const urlInputRef = ref<HTMLInputElement | null>(null);

/** 简单 URL 校验：必须以 http(s):// 开头 + 看起来像 .json 路径 */
function validateUrl(raw: string): string {
  const v = raw.trim();
  if (!v) return '请输入 URL';
  if (!/^https?:\/\//i.test(v)) return '仅支持 http:// 或 https:// 开头的远程 URL';
  try {
    new URL(v);
  } catch {
    return 'URL 格式不合法';
  }
  // .json 后缀友好提示（不强制——某些 CDN 会用 query / 重写路径）
  if (!/\.json(\?|#|$)/i.test(v)) {
    return '建议指向 .json 文件；当前 URL 可能不是配置文件';
  }
  return '';
}

const canSubmit = computed(() => {
  if (source.value === 'local') return true;
  return validateUrl(urlInput.value) === '' || urlInput.value.trim() !== '';
});

watch(visible, async (v) => {
  if (v) {
    // 重置状态 + 切到远程 tab 时聚焦输入框
    source.value = 'local';
    urlInput.value = '';
    urlError.value = '';
  }
});

watch(source, async (s) => {
  if (s === 'remote') {
    await nextTick();
    urlInputRef.value?.focus();
  }
  urlError.value = '';
});

function cancel(): void {
  current.value?.resolve(null);
  _queue.value.shift();
}

function submit(): void {
  if (source.value === 'local') {
    current.value?.resolve('local');
    _queue.value.shift();
    return;
  }
  trySubmitRemote();
}

function trySubmitRemote(): void {
  const v = urlInput.value.trim();
  const err = validateUrl(v);
  if (err) {
    // 仅当用户已经填了内容才弹错误；空 input 直接 disable submit
    urlError.value = err;
    return;
  }
  current.value?.resolve({ url: v });
  _queue.value.shift();
}

function onMaskClick(): void {
  cancel();
}
</script>

