  @changelog
  | 版本   | 变更说明                                                                |
  | v0.2.0 | 折叠分组：title + icon + 自定义色系，slot 内容可折叠                    |
  | v0.5.0 | 引入 level 概念：level=1 强分组(卡片)、level=2 弱分组(列表项+左色条)    |
  | v0.5.1 | 修复在 flex column 容器中被 shrink 压缩导致内容截断 (flex-shrink: 0)   |
  | v0.6.0 | 支持 required（标题加红 *）+ removable（标题右侧 − 按钮，emit remove） |
  /@changelog

  @author v_weiqinlin
-->
<template>
  <div class="collapse-section" :class="[`level-${level}`, { expanded: isExpanded }]"
    :style="{ '--section-color': color }">
    <button class="collapse-header" @click="toggle">
      <ChevronRight :size="level === 1 ? 13 : 12" class="collapse-arrow" />
      <component
        v-if="icon && level === 1"
        :is="icon"
        :size="14"
        :stroke-width="2"
        class="section-icon"
      />
      <span class="section-title">
        {{ title }}
        <span v-if="required" class="required-mark" title="必填字段">*</span>
      </span>
      <span v-if="badge" class="section-badge">{{ badge }}</span>
      <span v-if="!hasContent && level === 1" class="empty-flag">未配置</span>
      <span v-if="hasActions" class="header-actions" @click.stop>
        <slot name="actions" />
      </span>
      <button
        v-if="removable"
        class="header-remove-btn"
        title="移除该分组"
        @click.stop="emit('remove')"
      >
        <X :size="12" />
      </button>
    </button>
    <Transition name="me-collapse">
      <div v-if="isExpanded && hasContent" class="collapse-body">
        <slot />
      </div>
    </Transition>
  </div>
</template>

<script setup lang="ts">
import { ref, useSlots, computed } from 'vue';
import { ChevronRight, X } from 'lucide-vue-next';

const props = withDefaults(
  defineProps<{
    title: string;
    icon?: any;
    color?: string;
    expanded?: boolean;
    /** 层级：1=强分组(卡片), 2=弱分组(列表项) */
    level?: 1 | 2;
    /** 标题右侧的徽章（如计数 "3 项"、状态等） */
    badge?: string;
    /** 是否为必填字段（标题加红 *） */
    required?: boolean;
    /** 是否显示标题右侧 − 移除按钮 */
    removable?: boolean;
  }>(),
  { color: '#a1a1aa', expanded: false, level: 1, required: false, removable: false },
);

const emit = defineEmits<{
  (e: 'remove'): void;
}>();

const isExpanded = ref(props.expanded);
const slots = useSlots();
const hasContent = computed(() => !!slots.default && !!slots.default().length);
const hasActions = computed(() => !!slots.actions);

const toggle = () => {
  if (hasContent.value) isExpanded.value = !isExpanded.value;
};
</script>

<style scoped>
/* ==================== 通用基础 ==================== */
.collapse-section {
  --section-color: #a1a1aa;
  /* 关键：当置于 flex column 容器中时，禁止被 shrink 压缩
   * 否则当所有 section 总高度超过 .property-content 时，
   * 浏览器会按比例把每个 section 压扁，导致内容被 overflow:hidden 截断。
   */
  flex-shrink: 0;
}

.collapse-header {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  border: none;
  cursor: pointer;
  font-family: inherit;
  text-align: left;
  transition: background var(--me-trans-fast);
  outline: none;
  position: relative;
}

.collapse-arrow {
  color: var(--me-text-4);
  transition: transform var(--me-trans);
  flex-shrink: 0;
}

.collapse-section.expanded > .collapse-header > .collapse-arrow {
  transform: rotate(90deg);
}

.section-icon {
  flex-shrink: 0;
  color: var(--section-color);
}

.section-title {
  flex: 1;
  letter-spacing: 0.2px;
  transition: color var(--me-trans-fast);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.required-mark {
  color: var(--me-danger);
  font-weight: var(--me-fw-bold);
  font-family: var(--me-font-mono);
}

.section-badge {
  font-family: var(--me-font-mono);
  font-size: var(--me-fs-xs);
  color: var(--me-text-3);
  background: var(--me-bg-hover);
  padding: 1px 7px;
  border-radius: 999px;
}

.empty-flag {
  font-size: var(--me-fs-xs);
  color: var(--me-text-5);
  background: var(--me-bg-hover);
  padding: 1px 6px;
  border-radius: 3px;
}

.header-actions {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

/* 标题栏右侧的移除按钮：统一 SceneTreePanel 风格——默认隐形，header hover 才显出，
 * 自身 hover 浅红背景；无边框、无实色 background 干扰，视觉轻量 */
.header-remove-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--me-text-4);
  border-radius: 4px;
  cursor: pointer;
  opacity: 0;
  transition: all var(--me-trans-fast);
  flex-shrink: 0;
}

.collapse-header:hover .header-remove-btn {
  opacity: 1;
}

.header-remove-btn:hover {
  background: var(--me-danger-bg);
  color: var(--me-danger);
}

.me-collapse-enter-active,
.me-collapse-leave-active {
  transition: all var(--me-trans);
  overflow: hidden;
}

.me-collapse-enter-from,
.me-collapse-leave-to {
  max-height: 0;
  opacity: 0;
  padding-top: 0;
  padding-bottom: 0;
}

.me-collapse-enter-to,
.me-collapse-leave-from {
  max-height: 1200px;
  opacity: 1;
}

/* ==================== Level 1: 强分组（卡片） ==================== */
.collapse-section.level-1 {
  background: var(--me-bg-elevated-2);
  border: 1px solid var(--me-border);
  border-radius: var(--me-radius-md);
  overflow: hidden;
  transition: border-color var(--me-trans-fast);
}

.collapse-section.level-1.expanded {
  border-color: var(--me-border-strong);
}

.collapse-section.level-1 > .collapse-header {
  padding: 11px 12px;
  font-size: var(--me-fs-md);
  font-weight: var(--me-fw-medium);
}

.collapse-section.level-1 > .collapse-header:hover {
  background: var(--me-bg-hover);
}

.collapse-section.level-1.expanded > .collapse-header > .section-title {
  color: var(--section-color);
}

.collapse-section.level-1:not(.expanded) > .collapse-header > .section-title {
  color: var(--me-text-2);
}

.collapse-section.level-1 > .collapse-body {
  padding: 8px 12px 12px;
  border-top: 1px solid var(--me-border);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* 关键：collapse-body 内的所有直接子项也禁止被 shrink，
 * 否则嵌套 CollapseSection（如 lighting > 天空 > 子字段）会被等比压扁。 */
.collapse-section > .collapse-body > * {
  flex-shrink: 0;
}

/* ==================== Level 2: 弱分组（列表项+左色条） ==================== */
.collapse-section.level-2 {
  background: transparent;
  border: none;
  border-radius: var(--me-radius);
  position: relative;
  /* 关键：不裁剪 ::before（色条），但 body 展开仍由内部 transition 控制 */
}

/* 左侧细色条
 * 关键：附着在 .collapse-header 上，与 body 高度变化解耦，
 * 避免折叠/展开时色条因 section 高度变化而抖动重绘
 */
.collapse-section.level-2 > .collapse-header::after {
  content: '';
  position: absolute;
  left: -1px;
  top: 8px;
  bottom: 8px;
  width: 2px;
  border-radius: 0 2px 2px 0;
  background: var(--me-border);
  transition: background var(--me-trans-fast);
  pointer-events: none;
}

.collapse-section.level-2.expanded > .collapse-header::after {
  background: var(--section-color);
  opacity: 0.85;
}

.collapse-section.level-2 > .collapse-header {
  padding: 8px 10px 8px 14px;
  font-size: var(--me-fs-sm);
  font-weight: var(--me-fw-medium);
  background: var(--me-bg-input);
  border: 1px solid var(--me-border);
  border-radius: var(--me-radius);
  transition: all var(--me-trans-fast);
}

.collapse-section.level-2 > .collapse-header:hover {
  background: var(--me-bg-hover);
  border-color: var(--me-border-strong);
}

.collapse-section.level-2.expanded > .collapse-header {
  background: var(--me-bg-hover);
  border-color: var(--me-border-strong);
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}

.collapse-section.level-2 > .collapse-header > .collapse-arrow {
  color: var(--me-text-3);
}

.collapse-section.level-2 > .collapse-header > .section-title {
  color: var(--me-text-1);
  font-family: var(--me-font-mono);
  font-size: var(--me-fs-sm);
}

.collapse-section.level-2 > .collapse-body {
  padding: 10px 12px 12px;
  background: var(--me-bg-base);
  border: 1px solid var(--me-border-strong);
  border-top: none;
  border-bottom-left-radius: var(--me-radius);
  border-bottom-right-radius: var(--me-radius);
  display: flex;
  flex-direction: column;
  gap: 10px;
}
</style>

