<template>
  <div class="vec3">
    <div v-for="(v, i) in values" :key="i" class="axis-input" :data-axis="axisLabels[i]">
      <span class="axis-tag" :class="`axis-${axisLabels[i].toLowerCase()}`">
        {{ axisLabels[i] }}
      </span>
      <input
        class="axis-num me-mono"
        type="number"
        :value="v"
        :step="step"
        @input="onAxisInput(i, $event)"
      />
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed } from 'vue';

const props = withDefaults(
  defineProps<{
    values: number[];
    labels?: string;
    step?: number;
  }>(),
  { labels: 'X,Y,Z', step: 0.1 },
);

const emit = defineEmits<{
  /** 任一轴变化：emit 完整新数组（保持原数组其它项不变） */
  (e: 'update:values', v: number[]): void;
}>();

const axisLabels = computed(() => props.labels.split(','));

const onAxisInput = (axisIdx: number, e: Event) => {
  const raw = (e.target as HTMLInputElement).value;
  // 空字符串保持为 0；非数字回退为 0；保留 number 精度
  const num = raw === '' ? 0 : Number(raw);
  if (Number.isNaN(num)) return;
  // 复制原数组并替换对应轴
  const next = [
    Number(props.values[0] ?? 0),
    Number(props.values[1] ?? 0),
    Number(props.values[2] ?? 0),
  ];
  next[axisIdx] = num;
  emit('update:values', next);
};
</script>

